SELECT (SELECT count(*) FROM t4) AS table_rows,(SELECT sum(i) FROM t4) AS table_value_sum,(SELECT sum(CASE WHEN (rowid%2)=1 THEN i=rowid*2 ELSE i=rowid END) FROM t4) AS correct_values,(SELECT sum(CASE WHEN (rowid%2)=1 THEN t=printf('number %d',rowid*2) ELSE t=printf('number %d',rowid) END) FROM t4) AS correct_text,count(*) AS log_rows,sum(op='INSERT INTO t4') AS insert_logs,sum(op='UPDATE OF t4') AS update_logs,sum(op='DELETE OF t4') AS delete_logs,sum(CASE WHEN op='UPDATE OF t4' THEN r ELSE 0 END) AS updated_rowid_sum,sum(CASE WHEN op='UPDATE OF t4' THEN i ELSE 0 END) AS updated_value_sum,sum(length(t)) AS logged_text_length FROM log;